changeSet.sql:
INSERT INTO clinlims.menu (id, presentation_order, element_id, action_url, display_key, tool_tip_key, new_window, is_active, hide_in_old_ui) SELECT nextval('clinlims.menu_seq'), 30, 'menu_qa', '', 'sideNav.label.qa', 'sideNav.label.qa', false, true, true WHERE NOT EXISTS (SELECT 1 FROM clinlims.menu WHERE element_id = 'menu_qa');
INSERT INTO clinlims.menu (id, parent_id, presentation_order, element_id, action_url, display_key, tool_tip_key, new_window, is_active, hide_in_old_ui) SELECT nextval('clinlims.menu_seq'), (SELECT p.id FROM clinlims.menu p WHERE p.element_id = v.parent), v.ord, v.element_id, v.url, v.label, v.label, false, true, true FROM (VALUES ('menu_qa', 10, 'menu_qa_overview', '/qa/overview', 'sideNav.label.qa.overview'), ('menu_qa', 20, 'menu_qa_qc', '', 'sideNav.label.qa.qc'), ('menu_qa', 40, 'menu_qa_qi', '', 'sideNav.label.qa.qi'), ('menu_qa', 50, 'menu_qa_qms', '', 'sideNav.label.qa.qms') ) AS v(parent, ord, element_id, url, label) WHERE NOT EXISTS (SELECT 1 FROM clinlims.menu m WHERE m.element_id = v.element_id);
INSERT INTO clinlims.menu (id, parent_id, presentation_order, element_id, action_url, display_key, tool_tip_key, new_window, is_active, hide_in_old_ui) SELECT nextval('clinlims.menu_seq'), (SELECT p.id FROM clinlims.menu p WHERE p.element_id = v.parent), v.ord, v.element_id, v.url, v.label, v.label, false, true, true FROM (VALUES ('menu_qa_qc', 10, 'menu_qa_qc_dashboard', '/qa/qc/dashboard', 'sideNav.label.qa.qc.dashboard'), ('menu_qa_qc', 20, 'menu_qa_qc_alerts', '/qa/qc/alerts', 'sideNav.label.qa.qc.alerts'), ('menu_qa_qc', 30, 'menu_qa_qc_control_lots', '/qa/qc/control-lots', 'sideNav.label.qa.qc.controlLots'), ('menu_qa_qc', 40, 'menu_qa_qc_rule_config', '/qa/qc/rule-config', 'sideNav.label.qa.qc.ruleConfig'), ('menu_qa_qc', 50, 'menu_qa_qc_reagent_qc', '/qa/qc/reagent-qc', 'sideNav.label.qa.qc.reagentQc'), ('menu_qa_qc', 60, 'menu_qa_qc_manual_qc', '/qa/qc/manual-qc', 'sideNav.label.qa.qc.manualQc'), ('menu_qa_qi', 10, 'menu_qa_qi_dashboard', '/qa/qi/dashboard', 'sideNav.label.qa.qi.dashboard'), ('menu_qa_qi', 30, 'menu_qa_qi_config', '/qa/qi/config', 'sideNav.label.qa.qi.config'), ('menu_qa_qms', 30, 'menu_qa_qms_esig_log', '/qa/qms/e-signature-log', 'sideNav.label.qa.qms.esigLog'), ('menu_qa_qms', 40, 'menu_qa_qms_capa_register', '/qa/qms/capa-register', 'sideNav.label.qa.qms.capaRegister'), ('menu_qa_qms', 50, 'menu_qa_qms_accreditation', '/qa/qms/accreditation', 'sideNav.label.qa.qms.accreditation') ) AS v(parent, ord, element_id, url, label) WHERE NOT EXISTS (SELECT 1 FROM clinlims.menu m WHERE m.element_id = v.element_id);

rollback.sql:
UPDATE clinlims.menu
SET parent_id = (SELECT id FROM clinlims.menu WHERE element_id = 'menu_reports')
WHERE element_id = 'menu_reports_audittrail';

changeSet.sql:
UPDATE clinlims.menu SET is_active = true, action_url = '', parent_id = (SELECT id FROM clinlims.menu WHERE element_id = 'menu_qa'), presentation_order = 30 WHERE element_id = 'menu_eqa';
UPDATE clinlims.menu SET parent_id = (SELECT id FROM clinlims.menu WHERE element_id = 'menu_eqa'), presentation_order = 10 WHERE element_id = 'menu_eqa_tests';
UPDATE clinlims.menu SET parent_id = (SELECT id FROM clinlims.menu WHERE element_id = 'menu_eqa'), presentation_order = 20 WHERE element_id = 'menu_eqa_mgmt';

rollback.sql:
UPDATE clinlims.menu SET is_active = false, action_url = ''
WHERE element_id = 'menu_eqa';
UPDATE clinlims.menu SET parent_id = NULL
WHERE element_id IN ('menu_eqa_tests', 'menu_eqa_mgmt');

